     7→
     8→class AudioEngine {
     9→  final AudioPlayer _narration = AudioPlayer();
    10→  final AudioPlayer _soundscape = AudioPlayer();
    11→
    12→  bool _initialized = false;
    13→  Timer? _crossfadeTimer;
    14→  String? _currentSoundscapeUrl;
    15→
    16→  Future<void> ensureInitialized() async {
    17→    if (_initialized) {
    18→      return;
    19→    }
    20→
    21→    final session = await AudioSession.instance;
    22→    await session.configure(const AudioSessionConfiguration.music());
    23→
    24→    _soundscape.setLoopMode(LoopMode.one);
    25→    await _soundscape.setVolume(0.6);
    26→
    27→    _initialized = true;
    28→  }
    29→
    30→  Future<void> loadPage(PageData page) async {
    31→    await ensureInitialized();
    32→
    33→    final futures = <Future<void>>[];
    34→
    35→    if (page.narrationUrl != null && page.narrationUrl!.isNotEmpty) {
    36→      futures.add(_narration.setUrl(page.narrationUrl!).then((_) {}));
    37→    } else {
    38→      futures.add(_narration.stop());
    39→    }
    40→
    41→    if (page.soundscapeUrl != null && page.soundscapeUrl!.isNotEmpty) {
    42→      futures.add(_soundscape.setUrl(page.soundscapeUrl!).then((_) {}));
    43→      _currentSoundscapeUrl = page.soundscapeUrl;
    44→    } else {
    45→      futures.add(_soundscape.stop());
    46→      _currentSoundscapeUrl = null;
    47→    }
    48→
    49→    await Future.wait(futures);
    50→  }
    51→
    52→  Future<void> play() async {
    53→    await ensureInitialized();
    54→    await Future.wait([_narration.play(), _soundscape.play()]);
    55→  }
    56→
    57→  Future<void> pause() async {
    58→    await Future.wait([_narration.pause(), _soundscape.pause()]);
    59→  }
    60→
    61→  Future<void> transitionToPage(PageData nextPage) async {
    62→    await ensureInitialized();
    63→
    64→    final nextSoundscapeUrl = nextPage.soundscapeUrl;
    65→
    66→    if (nextSoundscapeUrl == null || nextSoundscapeUrl.isEmpty) {
    67→      await _soundscape.stop();
    68→      await _narration.stop();
    69→      _currentSoundscapeUrl = null;
    70→      return;
    71→    }
    72→
    73→    if (_currentSoundscapeUrl == nextSoundscapeUrl) {
    74→      if (nextPage.narrationUrl != null && nextPage.narrationUrl!.isNotEmpty) {
    75→        await _narration.setUrl(nextPage.narrationUrl!);
    76→        await _narration.play();
    77→      }
    78→      return;
    79→    }
    80→
    81→    _crossfadeTimer?.cancel();
    82→    await _soundscape.setVolume(0);
    83→    await loadPage(nextPage);
    84→    await _soundscape.play();
    85→    await _narration.play();
    86→
    87→    const steps = 15;
    88→    const duration = Duration(milliseconds: 1500);
    89→    const targetVolume = 0.6;
    90→    final tick = duration ~/ steps;
    91→    var currentStep = 0;
    92→
    93→    _crossfadeTimer = Timer.periodic(tick, (timer) async {
    94→      currentStep += 1;
    95→      final progress = currentStep / steps;
    96→      await _soundscape.setVolume(targetVolume * progress);
    97→      if (currentStep >= steps) {
    98→        timer.cancel();
    99→      }
   100→    });
   101→  }
   102→
   103→  Stream<Duration> get narrationPosition => _narration.positionStream;
   104→  Stream<bool> get narrationPlaying => _narration.playingStream;
   105→
   106→  Future<void> setNarrationVolume(double volume) =>
   107→      _narration.setVolume(volume);
   108→  Future<void> setSoundscapeVolume(double volume) =>
   109→      _soundscape.setVolume(volume);
   110→
   111→  Future<void> dispose() async {
   112→    _crossfadeTimer?.cancel();
   113→    await _narration.dispose();
   114→    await _soundscape.dispose();
   115→  }
   116→}
   117→

