     7→/// A singleton [CacheManager] that guards against SQLITE_BUSY errors.
     8→///
     9→/// The default [CacheManager] from `flutter_cache_manager` can throw
    10→/// `DatabaseException(database is locked (code 5 SQLITE_BUSY))` when the app
    11→/// was previously force-killed and a stale SQLite lock-file remains.
    12→///
    13→/// This class:
    14→///   1. Ensures a true single instance (compile-time singleton).
    15→///   2. Deletes stale `-wal` and `-shm` lock files on first access so the
    16→///      database can be opened cleanly.
    17→///   3. Uses a dedicated cache key to avoid collisions with any other cache.
    18→class ResilientCacheManager {
    19→  ResilientCacheManager._();
    20→
    21→  static const _key = 'storiaImageCache';
    22→
    23→  static CacheManager? _instance;
    24→
    25→  /// Returns the singleton [CacheManager], creating it on first call.
    26→  ///
    27→  /// On the very first invocation it also cleans up stale SQLite WAL/SHM files
    28→  /// left behind by a previous crashed process.
    29→  static Future<CacheManager> getInstance() async {
    30→    if (_instance != null) return _instance!;
    31→
    32→    await _cleanStaleLockFiles();
    33→
    34→    _instance = CacheManager(
    35→      Config(
    36→        _key,
    37→        stalePeriod: const Duration(days: 14),
    38→        maxNrOfCacheObjects: 200,
    39→      ),
    40→    );
    41→
    42→    return _instance!;
    43→  }
    44→
    45→  /// Synchronous accessor for use after [getInstance] has been awaited once
    46→  /// (e.g. in widget build methods). Falls back to [DefaultCacheManager] if
    47→  /// called before initialisation -- this is safe because [DefaultCacheManager]
    48→  /// is itself a singleton.
    49→  static CacheManager get instance =>
    50→      _instance ?? DefaultCacheManager();
    51→
    52→  /// Remove stale WAL/SHM journal files that cause SQLITE_BUSY on re-open.
    53→  static Future<void> _cleanStaleLockFiles() async {
    54→    try {
    55→      final dir = await getApplicationSupportDirectory();
    56→      final dbPath = p.join(dir.path, '$_key.db');
    57→
    58→      for (final suffix in ['-wal', '-shm']) {
    59→        final file = File('$dbPath$suffix');
    60→        if (await file.exists()) {
    61→          await file.delete();
    62→        }
    63→      }
    64→
    65→      // Also clean the default cache manager's DB that was previously crashing.
    66→      final filesDir = await getApplicationDocumentsDirectory();
    67→      // The default DB lives next to the files directory.
    68→      final parent = filesDir.parent;
    69→      final defaultDbPath = p.join(parent.path, 'files', 'libCachedImageData.db');
    70→      for (final suffix in ['-wal', '-shm']) {
    71→        final file = File('$defaultDbPath$suffix');
    72→        if (await file.exists()) {
    73→          await file.delete();
    74→        }
    75→      }
    76→    } catch (_) {
    77→      // Best-effort cleanup -- swallow errors so the app can still start.
    78→    }
    79→  }
    80→}
