    47→  Future<void> _resolveImageDimensions() async {
    48→    final imageUrl = widget.page.imageUrl;
    49→    if (imageUrl == null || imageUrl.isEmpty) {
    50→      return;
    51→    }
    52→
    53→    final completer = Completer<Size>();
    54→    final stream = NetworkImage(imageUrl).resolve(const ImageConfiguration());
    55→    late final ImageStreamListener listener;
    56→    listener = ImageStreamListener(
    57→      (image, _) {
    58→        if (!completer.isCompleted) {
    59→          completer.complete(
    60→            Size(image.image.width.toDouble(), image.image.height.toDouble()),
    61→          );
    62→        }
    63→        stream.removeListener(listener);
    64→      },
    65→      onError: (_, __) {
    66→        if (!completer.isCompleted) {
    67→          completer.complete(Size.zero);
    68→        }
    69→        stream.removeListener(listener);
    70→      },
    71→    );
    72→
    73→    stream.addListener(listener);
    74→    final size = await completer.future;
    75→    if (!mounted) {
    76→      return;
    77→    }
    78→    setState(() {
    79→      _sourceImageSize = size;
    80→    });
    81→  }
